mapper.update:
UPDATE session
   SET agent_id = #{newAgentId}, status = #{newStatus}, update_time = CURRENT_TIMESTAMP
 WHERE id = #{sessionId}
   AND tenant_code = #{tenantCode}
   AND agent_id = #{expectedAgentId}
   AND status = 3
   AND is_deleted = FALSE

mapper.select:
SELECT id
  FROM session
 WHERE tenant_code = #{tenantCode}
   AND id = #{sessionId}
   AND is_deleted = FALSE
 FOR UPDATE
